const CSRF_HEADER = "X-Puddly-CSRF";
const CSRF_COOKIE = "puddly_csrf";

function readCookie(name: string): string {
  if (typeof document === "undefined" || !document.cookie) return "";
  const parts = document.cookie.split(";");
  for (const part of parts) {
    const p = part.trim();
    if (p.startsWith(name + "=")) {
      try {
        return decodeURIComponent(p.slice(name.length + 1));
      } catch {
        return p.slice(name.length + 1);
      }
    }
  }
  return "";
}

function createRpc(opts: ClientOptions = {}) {
  const base = (opts.baseUrl ?? "").replace(/\/$/, "");
  const f = opts.fetch ?? fetch;
  return async function rpc<T = unknown>(
    operation: string,
    body?: Record<string, unknown>,
  ): Promise<RpcResult<T>> {
    try {
      const res = await f(`${base}/rpc/${operation}`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          [CSRF_HEADER]: readCookie(CSRF_COOKIE),
        },
        credentials: "include",
        body: JSON.stringify(body ?? {}),
      });
      const json = (await res.json()) as RpcResult<T>;
      return json;
    } catch (e) {
      const message = e instanceof Error ? e.message : String(e);
      return { ok: false, error: { code: "network", message } };
    }
  };
}

